import { Request, Response } from 'express';
import { CreateProjectUseCase } from '../../../application/use-cases/CreateProjectUseCase';
import { ListProjectsUseCase } from '../../../application/use-cases/ListProjectsUseCase';
import { requireString } from '../requestParsing';

export class ProjectController {
  constructor(
    private readonly createProject: CreateProjectUseCase,
    private readonly listProjects: ListProjectsUseCase,
  ) {}

  create = async (req: Request, res: Response): Promise<void> => {
    const project = await this.createProject.execute({ name: requireString(req.body, 'name') });
    res.status(201).json(project);
  };

  list = async (_req: Request, res: Response): Promise<void> => {
    res.json(await this.listProjects.execute());
  };
}

=====SOURCE-END=====

