import { Request, Response } from 'express';
import { AddTaskToProjectUseCase } from '../../../application/use-cases/AddTaskToProjectUseCase';
import { AssignTaskUseCase } from '../../../application/use-cases/AssignTaskUseCase';
import { ListProjectTasksUseCase } from '../../../application/use-cases/ListProjectTasksUseCase';
import { MarkTaskDoneUseCase } from '../../../application/use-cases/MarkTaskDoneUseCase';
import { optionalString, requireString } from '../requestParsing';

export class TaskController {
  constructor(
    private readonly addTask: AddTaskToProjectUseCase,
    private readonly listProjectTasks: ListProjectTasksUseCase,
    private readonly assignTask: AssignTaskUseCase,
    private readonly markTaskDone: MarkTaskDoneUseCase,
  ) {}

  create = async (req: Request, res: Response): Promise<void> => {
    const task = await this.addTask.execute({
      projectId: requireString(req.params, 'projectId'),
      title: requireString(req.body, 'title'),
      description: requireString(req.body, 'description'),
      dueDate: optionalString(req.body, 'dueDate'),
      status: optionalString(req.body, 'status'),
    });
    res.status(201).json(task);
  };

  listByProject = async (req: Request, res: Response): Promise<void> => {
    const tasks = await this.listProjectTasks.execute({
      projectId: requireString(req.params, 'projectId'),
      status: optionalString(req.query, 'status'),
      assigneeId: optionalString(req.query, 'assigneeId'),
    });
    res.json(tasks);
  };

  assign = async (req: Request, res: Response): Promise<void> => {
    const task = await this.assignTask.execute({
      taskId: requireString(req.params, 'taskId'),
      userId: requireString(req.body, 'userId'),
    });
    res.json(task);
  };

  markDone = async (req: Request, res: Response): Promise<void> => {
    const task = await this.markTaskDone.execute(requireString(req.params, 'taskId'));
    res.json(task);
  };
}

=====SOURCE-END=====

